import{G as e,W as t,n,rt as r}from"./chunks/framework.CHX_0itn.js";var i=JSON.parse(`{"title":"HTTP User-Agent 检测机制与原理","description":"","frontmatter":{"title":"HTTP User-Agent 检测机制与原理"},"headers":[],"relativePath":"traditional/UA.md","filePath":"traditional/UA.md"}`),a={name:`traditional/UA.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="🪪-http-user-agent-ua-检测原理" tabindex="-1">🪪 HTTP User-Agent (UA) 检测原理 <a class="header-anchor" href="#🪪-http-user-agent-ua-检测原理" aria-label="Permalink to “🪪 HTTP User-Agent (UA) 检测原理”">​</a></h1><p><strong>HTTP User-Agent（UA）检测</strong>属于应用层的终端指纹识别，受限于 TLS/HTTPS 协议的端到端加密机制，网关探针仅能抓取并解析明文 HTTP 流量中的 UA 报文。</p><h2 id="❓-什么是-user-agent" tabindex="-1">❓ 什么是 User-Agent <a class="header-anchor" href="#❓-什么是-user-agent" aria-label="Permalink to “❓ 什么是 User-Agent”">​</a></h2><p>User-Agent 是 HTTP/HTTPS 请求头（Header）中的一个字符串字段。它的主要作用是<strong>向目标服务器标识当前发起请求的客户端类型、操作系统、浏览器版本及内核信息</strong>。</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>客户端（浏览器、App、系统服务）在发起 HTTP 请求时，会在包头带上User-Agent，以表明身份<br> 例如：“我是运行在 Windows 11 上的 Chrome 浏览器”或“运行在 iOS 26 上的Safari浏览器”</p></div><h3 id="📄-常见操作系统的典型-ua-关键字" tabindex="-1">📄 常见操作系统的典型 UA 关键字 <a class="header-anchor" href="#📄-常见操作系统的典型-ua-关键字" aria-label="Permalink to “📄 常见操作系统的典型 UA 关键字”">​</a></h3><p>网关探针通常不需要解析完整的字符串，只需提取其中的<strong>操作系统核心关键字</strong>：</p><table tabindex="0"><thead><tr><th style="text-align:left;">操作系统类型</th><th style="text-align:left;">典型 UA 关键特征</th><th style="text-align:left;">实际请求示例片段</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Windows 10/11</strong></td><td style="text-align:left;"><code>Windows NT 10.0; Win64</code></td><td style="text-align:left;"><code>Mozilla/5.0 (Windows NT 10.0; Win64; x64)...</code></td></tr><tr><td style="text-align:left;"><strong>Android</strong></td><td style="text-align:left;"><code>Android &lt;版本号&gt;</code></td><td style="text-align:left;"><code>Mozilla/5.0 (Linux; Android 16; Pixel 9 Pro)...</code></td></tr><tr><td style="text-align:left;"><strong>iOS</strong></td><td style="text-align:left;"><code>iPhone OS + Version/&lt;版本号&gt;</code></td><td style="text-align:left;"><code>Mozilla/5.0 (iPhone; CPU iPhone OS 18_6 like Mac OS X)...</code></td></tr><tr><td style="text-align:left;"><strong>macOS</strong></td><td style="text-align:left;"><code>Macintosh; Intel Mac OS X</code></td><td style="text-align:left;"><code>Mozilla/5.0 (Macintosh; Intel Mac OS X 10_15_7)...</code></td></tr></tbody></table><details class="details custom-block"><summary>为什么 iOS 26 和 macOS 26 UA 里的版本号对不上？</summary><p>从 iOS 26（Safari 26.0）开始，Safari 的 UA 中 <strong><code>iPhone OS</code> 后面的系统版本号不再反映真实系统版本</strong>，而是被固定为 <strong><code>18_6</code></strong>（即 iOS 26 发布前最后一个版本）。这不是解析错误，而是 <strong>Apple 有意为之的“版本冻结”策略</strong>，目的是削弱用户被动指纹追踪。</p><p><strong>第三方浏览器的差异</strong>：Chrome 等基于 Chromium 的浏览器和 Firefox 上的 UA <strong>不受冻结影响</strong>，仍会报告真实的系统版本。</p><p>macOS 上的 Safari 早在 2017 年就已将系统版本冻结在 <code>10_15_7</code>（macOS Catalina 的版本号），无论实际运行的是 macOS 15 Sequoia 还是 macOS 26 Tahoe，Safari 的 UA 中永远是 <code>Intel Mac OS X 10_15_7</code>。</p><h3 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to “参考文章”">​</a></h3><ul><li><strong>Apple Developer</strong>: <a href="https://developer.apple.com/documentation/safari-release-notes/safari-26-release-notes" target="_blank" rel="noreferrer">Safari 26 Release Notes</a></li></ul></details><h2 id="🔬-校园网检测-ua-的原理" tabindex="-1">🔬 校园网检测 UA 的原理 <a class="header-anchor" href="#🔬-校园网检测-ua-的原理" aria-label="Permalink to “🔬 校园网检测 UA 的原理”">​</a></h2><p>校园网网关通过在出口处对 <strong>明文 HTTP 流量</strong> 进行实时抓包，读取数据包头部的 <code>User-Agent</code> 字段。</p><h3 id="_1-正常直连-未挂载路由器" tabindex="-1">1. 正常直连（未挂载路由器） <a class="header-anchor" href="#_1-正常直连-未挂载路由器" aria-label="Permalink to “1. 正常直连（未挂载路由器）”">​</a></h3><p>当单台设备直接连接校园网时，无论发起多少明文 HTTP 请求，网关收集到的 UA 操作系统特征保持高度一致。</p><table tabindex="0"><thead><tr><th style="text-align:left;">设备类型</th><th style="text-align:left;">请求流量类型</th><th style="text-align:left;">抓取的明文 HTTP UA</th><th style="text-align:left;">校园网网关判定</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Windows 电脑</strong></td><td style="text-align:left;">明文 HTTP</td><td style="text-align:left;"><code>Windows NT 10.0</code></td><td style="text-align:left;">唯一设备（Windows）</td></tr><tr><td style="text-align:left;"><strong>Android 手机</strong></td><td style="text-align:left;">明文 HTTP</td><td style="text-align:left;"><code>Android 16</code></td><td style="text-align:left;">唯一设备（Android）</td></tr></tbody></table><h3 id="_2-挂载路由器-经过路由-nat-转发" tabindex="-1">2. 挂载路由器（经过路由 NAT 转发） <a class="header-anchor" href="#_2-挂载路由器-经过路由-nat-转发" aria-label="Permalink to “2. 挂载路由器（经过路由 NAT 转发）”">​</a></h3><p>宿舍接入路由器后，多台不同系统的设备通过 NAT 转换共享同一个公网 IP 地址上网：</p><table tabindex="0"><thead><tr><th style="text-align:left;">下挂设备组合</th><th style="text-align:left;">抓取的明文 HTTP UA</th><th style="text-align:left;">校园网网关判定</th></tr></thead><tbody><tr><td style="text-align:left;">Windows 电脑 + iPhone</td><td style="text-align:left;"><code>Windows NT 10.0</code> 与 <code>iPhone OS</code> 混合出现</td><td style="text-align:left;">⚠️ <strong>封禁或增加封禁概率</strong></td></tr></tbody></table>`,17)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};